// FindRoomAlias retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindRoomAlias(ctx context.Context, exec boil.ContextExecutor, tenantID string, alias string, selectCols ...string) (*RoomAlias, error) {
	roomAliasObj := &RoomAlias{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from \"room_aliases\" where \"tenant_id\"=$1 AND \"alias\"=$2", sel,
	)

	q := queries.Raw(query, tenantID, alias)

	err := q.Bind(ctx, exec, roomAliasObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "dbpostgres: unable to select from room_aliases")
	}

	if err = roomAliasObj.doAfterSelectHooks(ctx, exec); err != nil {
		return roomAliasObj, err
	}

	return roomAliasObj, nil
}

